// --- 1. Lectura de variables globales ---
const armado = global.get("val_registro_0") || 0;
const s1 = global.get("val_registro_1") || 0;
const s2 = global.get("val_registro_4") || 0;

const chatId = env.get("TELEGRAM_CHAT_ID");

// --- 2. Lógica de Alerta Unificada ---
let valorSirena = 0;
let mensajeTelegram = null;
let zonaDetectada = "";

if (armado === 1) {
    if (s1 === 1) zonaDetectada = "Puerta Principal (Z1)";
    if (s2 === 1) zonaDetectada = (zonaDetectada === "") ? "Célula Robótica (Z2)" : "Z1 y Z2";

    if (zonaDetectada !== "") {
        valorSirena = 1;
        mensajeTelegram = {
            t0: Date.now(), //detección
            payload: {
                chatId: chatId,
                type: 'message',
                content: `🚨 ALERTA DE SEGURIDAD: Intrusión detectada en ${zonaDetectada}. Sirena activa.`
            }
        };
    }
}

// --- 3. Paquete para escribir en el Registro 2 (Sirena) ---
const ordenPLC = {
    value: valorSirena,
    fc: 6,
    unitid: 1,
    address: 2,
    quantity: 1
};

return [mensajeTelegram, { payload: ordenPLC }];

var fc = 16;             // Write Multiple Registers
var sa = 40002;              // 0 = primer holding register (40001)
var addresses = 1;       // cantidad de registros
var value = 1;           // valor a escribir

var buf = Buffer.alloc(addresses * 2);
buf.writeInt16BE(value, 0);

var values = [];
for (var i = 0; i < buf.length; i += 2) {
    values.push(buf.readInt16BE(i));
}

msg.slave_ip = "127.0.0.1";
msg.payload = {
    value: values,
    fc: fc,
    unitid: 1,
    address: sa,
    quantity: addresses
};

return msg;

// --- 1. Seguridad: Verificar que llegan datos ---
if (!msg.responseBuffer || !msg.responseBuffer.buffer) return null;
const rawBuffer = Buffer.from(msg.responseBuffer.buffer);

// Seguridad extra: Si el buffer es muy corto, no leemos para evitar error
if (rawBuffer.length < 6) return null;

// --- 2. EL CAMBIO CLAVE ---
// Leemos en el byte 4 (que corresponde al inicio del 3er registro/Sirena)
var estadoSirena = rawBuffer.readUInt16BE(4);

// --- 3. Lógica Visual ---
if (estadoSirena === 1) {
    msg.payload = "🚨 PELIGRO - SIRENA SONANDO";
    msg.color = "red";   // Esto pondrá el texto rojo si usas un nodo Text
} else {
    msg.payload = "✅ TRANQUILO - SISTEMA OK";
    msg.color = "green"; // Esto pondrá el texto verde
}

return msg;

// El nodo Status nos envía información sobre el color del puntito del nodo Modbus
// msg.status.fill puede ser "green", "red", "yellow" o "grey"

var estado = msg.status;

if (estado && (estado.fill === "green" || estado.text.includes("active"))) {
    // Si el punto es verde o dice "active"
    msg.payload = "🟢 CONEXIÓN ESTABLE";
    msg.color = "green"; // Texto verde en el dashboard
} else {
    // Si es rojo, amarillo o gris (desconectado)
    msg.payload = "🔴 ERROR DE CONEXIÓN PLC";
    msg.color = "red";   // Texto rojo y llamativo
}

return msg;

// 1. Seguridad básica
if (!msg.responseBuffer || !msg.responseBuffer.buffer) return null;
const rawBuffer = Buffer.from(msg.responseBuffer.buffer);

// 2. Mapeo de Registros (Offset de 2 bytes)
var estadoSistema = rawBuffer.readUInt16BE(0); // Reg 0: Alarma
var sensorActivo = rawBuffer.readUInt16BE(2); // Reg 1: Sensor 1
var reg2_sirena = rawBuffer.readUInt16BE(4); // Reg 2: Sirena
var r3 = rawBuffer.readUInt16BE(6); // Reg 3: Apertura
var reg4_sensor2 = rawBuffer.readUInt16BE(8); // Reg 4: Sensor 2

// 3. Guardar en memoria global para otros nodos
global.set("val_registro_0", estadoSistema);
global.set("val_registro_1", sensorActivo);
global.set("val_registro_2", reg2_sirena);
global.set("val_registro_3", r3);
global.set("val_registro_4", reg4_sensor2);

// 4. Lógica visual para el Dashboard
if (sensorActivo === 1 || reg4_sensor2 === 1) {
    let zona = (sensorActivo === 1) ? "ZONA 1" : "ZONA 2";
    if (sensorActivo === 1 && reg4_sensor2 === 1) zona = "ZONAS 1 y 2";

    msg.payload = `🚨 INTRUSIÓN: ${zona}`;
    msg.color = "white";
    msg.background = "red";
} else {
    msg.payload = "✅ Sistema Despejado";
    msg.color = "grey";
    msg.background = "white";
}

return msg;

if (!msg.responseBuffer || !msg.responseBuffer.buffer) return null;
const rawBuffer = Buffer.from(msg.responseBuffer.buffer);

// 1. Leemos los dos sensores
var s1 = rawBuffer.readUInt16BE(2); // Registro 1
var s2 = rawBuffer.readUInt16BE(8); // Registro 4

// 2. Enviamos los dos mensajes de forma explícita
node.send({ payload: s1, topic: "Puerta Principal" });
node.send({ payload: s2, topic: "Célula Robótica" });

// 3. Importante: no devolvemos nada para evitar el mensaje vacío
return null;

var estadoAnterior = context.get('estadoAnterior') || false;
var tiempoInicio = context.get('tiempoInicio') || 0;

var texto = msg.payload.toString().toUpperCase();
var hayIntrusion = texto.includes("🚨") || texto.includes("INTRUSIÓN");

var ahora = new Date();
var lineaCSV = null;

if (hayIntrusion && !estadoAnterior) {
    context.set('tiempoInicio', ahora.getTime());
    lineaCSV = `${ahora.toLocaleDateString()};${ahora.toLocaleTimeString()};🔴 INICIO: ${texto};-\n`;
}
else if (!hayIntrusion && estadoAnterior) {
    var duracionSeg = ((ahora.getTime() - tiempoInicio) / 1000).toFixed(1);
    lineaCSV = `${ahora.toLocaleDateString()};${ahora.toLocaleTimeString()};🟢 SISTEMA DESPEJADO;Duración: ${duracionSeg} s\n`;
}

context.set('estadoAnterior', hayIntrusion);

if (lineaCSV) {
    msg.payload = lineaCSV;
    return msg;
} else {
    return null;
}

// Recuperamos el PIN que escribiste
var pinRecibido = flow.get("pinIngresado");
var pinCorrecto = "1234"; // Tu contraseña


if (pinRecibido === pinCorrecto) {
    // CASO 1: ÉXITO
    return [{ payload: "Contraseña Correcta" }, null];
} else {
    // CASO 2: FALLO
    // Enviamos "RESET" al template para ocultar el botón verde
    // Enviamos el mensaje de error a la notificación
    return [{ payload: "Contraseña Incorrecta" }, { payload: "⛔ PIN INCORRECTO" }];
}

// El nodo ui_control envía "connect" cuando abres la web
if (msg.payload === "connect") {
    // Si es una conexión nueva, forzamos ir a la pestaña principal
    // IMPORTANTE: Pon aquí el nombre EXACTO de tu pestaña principal
    msg.payload = { tab: "Panel de Control" }; 
    return msg;
}

// El nodo Modbus Read devuelve un array, ej: [1, 0, 0]
// Cogemos solo la primera posición (Register 0)
msg.payload = msg.payload[0];
return msg;

// Definimos el mensaje
msg.payload = {
    chatId: 643121614,  // Tu ID fijo (esto está bien para tu TFG)
    type: 'message',
    content: "✅ Alarma ACTIVADA remotamente"
};

return msg;

// Definimos el mensaje
msg.payload = {
    chatId: 643121614,  // Tu ID fijo (esto está bien para tu TFG)
    type: 'message',
    content: "⛔ Alarma DESACTIVADA remotamente"
};

return msg;

let alarmaArmada = global.get("val_registro_0") || 0; // Registro 0
let sensor1 = global.get("val_registro_1") || 0; // Registro 1 (Ultrasonidos)
let sirena = global.get("val_registro_2") || 0; // Registro 2
let sensor2 = global.get("val_registro_4") || 0; // Registro 4 (Pin 14)

msg.payload = [
    {
        "name": "Puerta Principal",
        "status": sensor1 === 0 ? "Cerrada" : "¡MOVIMIENTO!",
        "icon": "sensor_door",
        "color": sensor1 === 0 ? "verde" : "rojo"
    },
    {
        "name": "Célula Robótica",
        "status": sensor2 === 0 ? "Segura" : "¡ABIERTA!",
        "icon": "precision_manufacturing",
        "color": sensor2 === 0 ? "verde" : "rojo"
    },
    {
        "name": "Estado Alarma",
        "status": alarmaArmada === 1 ? "ARMADA" : "Desarmada",
        "icon": alarmaArmada === 1 ? "security" : "lock_open",
        "color": alarmaArmada === 1 ? "azul" : "gris"
    },
    {
        "name": "Sirena Local",
        "status": sirena === 1 ? "ACTIVA" : "Silencio",
        "icon": "notifications_active",
        "color": sirena === 1 ? "rojo" : "gris"
    }
];

return msg;

let accion = parseInt(msg.payload.accion);

// 2. Consultamos el estado de PELIGRO (Registro 3) en la memoria global
// Usamos el nombre que definimos en el nodo de mapeo anterior
let peligroActivo = global.get("val_registro_2") || 0; // Registro 3 (Peligro)

// 3. VALIDACIÓN DE SEGURIDAD (Interbloqueo)
// Si el usuario intenta abrir (1) pero la alarma está disparada (1), bloqueamos la orden.
if (accion === 1 && peligroActivo === 1) {
    // Enviamos una alerta al log de Node-RED
    node.warn("BLOQUEO DE SEGURIDAD: No se puede abrir la cerradura mientras la alarma está activa.");

    // Devolvemos un mensaje de error para la App (Salida 1) y anulamos el envío a Modbus
    msg.payload = { 
        status: "error", 
        message: "Acceso denegado: Alarma en curso" 
    };
    return [msg, null]; 
}

// 4. Si es seguro, preparamos el paquete para Modbus-Flex-Write
// Escribimos en la dirección 3 (que corresponde al Registro 4 en ModbusPal)
const ordenModbus = {
    value: accion,
    fc: 6,           // Escribir un solo registro (Preset Single Register)
    unitid: 1,       // ID del esclavo Modbus
    address: 3,      // Dirección 3 = Registro 4
    quantity: 1
};

// Preparamos la respuesta de éxito para la App
msg.payload = { 
    status: "ok", 
    message: accion === 1 ? "Cerradura Abierta" : "Cerradura Bloqueada" 
};

// 5. Salidas: 
// [Respuesta HTTP para la App, Orden para el PLC Modbus]
return [msg, { payload: ordenModbus }];

// Forzamos la acción a 1 (Armar)
let accion = 1;

// Salida 1: Respuesta inmediata para Flutter (Pone el SnackBar VERDE)
msg.payload = { status: "ok", message: "Alarma Armada" };

// Salida 2: Configuración Modbus
const ordenModbus = {
    value: accion,
    fc: 6,
    unitid: 1,
    address: 0, // Ajusta a tu registro de alarma
    quantity: 1
};

return [msg, { payload: ordenModbus }];

// Forzamos la acción a 0 (Desarmar)
let accion = 0;

// Salida 1: Respuesta para Flutter
msg.payload = { status: "ok", message: "Alarma Desactivada" };

// Salida 2: Configuración Modbus
const ordenModbus = {
    value: accion,
    fc: 6,
    unitid: 1,
    address: 0, 
    quantity: 1
};

return [msg, { payload: ordenModbus }];

const t1 = Date.now();
const latencia_ms = t1 - msg.t0;

// Guardamos la latencia en un mensaje aparte para el fichero CSV
const registro = {
    payload: new Date().toISOString() + ";" + latencia_ms + "\n"
};

// devolvemos el mensaje original (para que siga a Telegram) 
// y el registro de latencia (para guardarlo en fichero) por dos salidas
return [msg, registro];
